package engine

import "context"

// Descriptions are written for the agent to choose a tool by outcome, so they say what the person gets, not how it is stored.
func (s *Service) registerOperations() {
	register(s, "tracker_catalog_get", "Read the supported versioned client catalogs (the block types each app and platform renders) before composing a view of a goal. Blocks bind to real goal data; never generate code or observations.", false, getTrackerCatalog)
	register(s, "goal_measurements_record", "Record an actual numeric observation for a goal's defined metric, with its observed time and notes. Never invent values or treat routine completion as an outcome measurement.", true, recordMeasurement)
	register(s, "goal_measurements_update", "Correct a recorded observation using the version last read; preserves its time unless supplied.", true, updateMeasurement)
	register(s, "goal_measurements_delete", "Remove an erroneous observation from the tracker; its audit history remains.", true, deleteMeasurement)

	register(s, "batch_apply", "Create a plan's records together, all or nothing: routines (with their nudges), a goal that uses them, reminders, plan items. Operations run in order, and each new record carries an id you chose so a later operation can refer to it. Run batch_dry_run on the same operations first and fix what it reports. If any operation fails, nothing is created. The person must approve it before it runs.", true, s.batchApply)
	register(s, "batch_undo", "Undo a batch_apply plan as a whole: removes the goal (archived), routines, reminders, plan items and view that plan created, newest first, in one transaction. Pass the idempotency_key the batch_apply used. Records already removed are reported, not an error; links a plan made between existing records are listed as not undone.", true, s.batchUndo)
	registerKeyless(s, "batch_dry_run", "Run a plan exactly as batch_apply would, then undo it, so every rule is checked and nothing is created. Use it on the same operations before batch_apply.", s.batchDryRun)
	register(s, "views_create", "Create a view of a goal: a manifest of blocks (trend, check-in, milestones, routine consistency, link) that refer to the goal and to the metrics it defines. Read tracker_catalog_get first and use the requesting client's exact catalog_id. A metric with a source is read live from that data engine; a metric without one is logged by hand. A view holds no observations and no markup. Create it as the last step of a batch_apply plan, after the goal it is a view of.", true, createView)
	register(s, "views_update", "Change a view's metrics and blocks using the version last read; both lists replace the current ones. A metric that has recorded observations must stay, in the same unit. Use this when the person asks to change what a goal's view shows.", true, updateView)
	register(s, "views_delete", "Remove a view from a goal; the goal and its records stay.", true, deleteView)
	register(s, "views_state", "Open a goal's tracker for one client catalog: its view (or null) and the observations recorded against the goal's metrics. Never substitute another app's view.", false, viewState)
	register(s, "views_get", "Read one view by id.", false, getView)
	register(s, "views_list", "List the views of a goal, optionally only the one for a client catalog.", false, listViews)
	register(s, "reminders_create", "Create a reminder for the person: something to be reminded of, optionally at a time and optionally repeating (daily, weekly on chosen weekdays, or monthly). Use this for a one-off cue or an event (call Sam at 5, pay rent on the 1st), never for a behaviour the person wants to repeat and track, which is a routine (routines_create). Only for something the person asked to be reminded of: it appears on their Today screen. Never create one to schedule a prompt for a routine or goal; a routine's prompts are its nudges (nudges_set) and a goal is followed through its routines and check-ins. When it is due you are woken to check it is still wanted and tell the person with notify_user.", true, createReminder)
	register(s, "reminders_get", "Read one reminder, including whether it is done, snoozed or repeating.", false, func(c context.Context, u *unit, in GetInput) (Reminder, error) { return u.getReminder(c, in.ID, false) })
	register(s, "reminders_list", "List the person's reminders: pending by default, or done or all, optionally within a due range or matching text. Soonest first; undated last.", false, listReminders)
	register(s, "reminders_update", "Replace a reminder's editable fields (title, notes, due time, zone, repeat, link) using the version you last read. Changing the due time clears any snooze.", true, updateReminder)
	register(s, "reminders_agenda", "A day's cues, one entry per occurrence, each upcoming, due (fired, not yet cleared) or acknowledged. A repeating reminder appears once for each time it falls that day. This is what the person's Today screen shows.", false, remindersAgenda)
	register(s, "reminders_ack", "Clear one occurrence of a reminder (\"Got it\"). A one-off is finished by it; a repeating reminder carries on and only that occurrence is cleared. Use reminders_complete to finish a reminder outright.", true, ackReminder)
	register(s, "reminders_complete", "Mark a reminder done. A repeating reminder stays pending and moves to its next occurrence if it was due.", true, completeReminder)
	register(s, "reminders_snooze", "Be reminded again at a later time without changing the reminder's schedule.", true, snoozeReminder)
	register(s, "reminders_delete", "Delete a reminder (it can be restored).", true, func(c context.Context, u *unit, in EditInput) (Reminder, error) {
		return lifecycleReminder(c, u, in, false)
	})
	register(s, "reminders_restore", "Restore a deleted reminder.", true, func(c context.Context, u *unit, in EditInput) (Reminder, error) {
		return lifecycleReminder(c, u, in, true)
	})
	register(s, "settings_get", "Read the person's settings: their time zone (which decides what 'today' means) and working hours.", false, func(c context.Context, u *unit, _ struct{}) (Settings, error) { return u.getSettings(c) })
	register(s, "settings_set", "Set the person's time zone and working hours (versioned). Set the time zone first: today's plan and closing the day depend on it.", true, setSettings)
	register(s, "schedules_create", "Create a recurring prompt the person asked you to run, such as 'every Sunday evening, review my week'. It appears in their app where they can pause or edit it. Use this, not a private wake, for anything the person asked to happen on a schedule; use a wake only for your own follow-ups. When it fires you are woken with the instruction. To give a goal a regular check-in, link the goal (link entity goal): you are then woken to look at its progress and offer a smaller next step if it has stalled.", true, createSchedule)
	register(s, "schedules_get", "Read one schedule, including when it next fires.", false, func(c context.Context, u *unit, in GetInput) (Schedule, error) { return u.getSchedule(c, in.ID, false) })
	register(s, "schedules_list", "List the person's recurring prompts, soonest first.", false, listSchedules)
	register(s, "schedules_update", "Replace a schedule's name, instruction, time, repeat or enabled flag using the version you last read.", true, updateSchedule)
	register(s, "schedules_delete", "Delete a schedule (it can be restored).", true, func(c context.Context, u *unit, in EditInput) (Schedule, error) {
		return lifecycleSchedule(c, u, in, false)
	})
	register(s, "schedules_restore", "Restore a deleted schedule; it resumes from now.", true, func(c context.Context, u *unit, in EditInput) (Schedule, error) {
		return lifecycleSchedule(c, u, in, true)
	})
	register(s, "monitors_create", "Create a monitor: something the person asked you to keep an eye on, checked on an interval (15 minutes to 31 days), with the person told only when it matters. It appears in their app where they can pause or edit it. Use this, not a private wake, for anything the person asked you to watch. When a check is due you are woken with the objective: check it, call monitors_record with what you found, and only if the person should hear about it set triggered and call notify_user.", true, createMonitor)
	register(s, "monitors_get", "Read one monitor, including its last result and when it is next checked.", false, func(c context.Context, u *unit, in GetInput) (Monitor, error) { return u.getMonitor(c, in.ID, false) })
	register(s, "monitors_list", "List the person's monitors, next check first.", false, listMonitors)
	register(s, "monitors_update", "Replace a monitor's name, objective, interval or enabled flag using the version you last read.", true, updateMonitor)
	register(s, "monitors_record", "Record the outcome of a check you just ran: one line on what you found, and whether the person should be told. Call it every time a monitor wakes you, including when nothing needs saying.", true, recordCheck)
	register(s, "monitors_delete", "Delete a monitor (it can be restored).", true, func(c context.Context, u *unit, in EditInput) (Monitor, error) {
		return lifecycleMonitor(c, u, in, false)
	})
	register(s, "monitors_restore", "Restore a deleted monitor; it resumes from now.", true, func(c context.Context, u *unit, in EditInput) (Monitor, error) {
		return lifecycleMonitor(c, u, in, true)
	})
	register(s, "goals_create", "For a client advertising a tracker catalog, read tracker_catalog_get and include a tailored tracker definition. Create a goal: an END STATE the person wants to reach (\"run a 10k by March\", \"lose 5 kg\"). Never use it for a behaviour that repeats forever (drinking water daily is a routine). Steps are ONE-OFF tasks, small and concrete, 10-30 minutes, so there is always a next action. Anything done repeatedly is a routine, not a step: look at the person's existing routines first, pass the ones that serve this goal in routine_ids, and create a routine (routines_create) for what is missing.", true, createGoal)
	register(s, "goals_link_routine", "Say that a routine serves a goal (idempotent). Use this when the person has a routine that moves a goal forward, instead of copying it into the goal's steps. Look at their existing routines first and link what already fits. If one of the goal's steps only repeats that routine (\"log meals today\"), remove the step with steps_delete so the same thing is not tracked twice.", true, func(c context.Context, u *unit, in LinkRoutineInput) (Goal, error) {
		return linkGoalRoutine(c, u, in, true)
	})
	register(s, "goals_unlink_routine", "Say that a routine no longer serves a goal. The routine itself is untouched.", true, func(c context.Context, u *unit, in LinkRoutineInput) (Goal, error) {
		return linkGoalRoutine(c, u, in, false)
	})
	register(s, "goals_get", "Read a goal with its steps, progress and next step.", false, func(c context.Context, u *unit, in GetInput) (Goal, error) { return u.getGoal(c, in.ID, false) })
	register(s, "goals_list", "List the person's goals with their steps, progress and next step. State deleted means archived.", false, listGoals)
	register(s, "goals_update", "Replace a goal's title, reason and weekly target using the version you last read.", true, updateGoal)
	register(s, "goals_archive", "Archive a goal (it can be restored).", true, func(c context.Context, u *unit, in EditInput) (Goal, error) { return lifecycleGoal(c, u, in, false) })
	register(s, "goals_restore", "Restore an archived goal.", true, func(c context.Context, u *unit, in EditInput) (Goal, error) { return lifecycleGoal(c, u, in, true) })
	register(s, "steps_add", "Add a small, concrete step to a goal, at the end or at a position. Use this when the person is stuck: a smaller first step (2-5 minutes) is better than a bigger plan.", true, addStep)
	register(s, "steps_update", "Change a step's title or minutes using the version you last read.", true, updateStep)
	register(s, "steps_complete", "Mark a step done, or reopen it with done false.", true, completeStep)
	register(s, "steps_reorder", "Put a goal's steps in a new order; list every step once.", true, reorderSteps)
	register(s, "steps_delete", "Remove a step. This cannot be undone; add it again if needed.", true, deleteStep)
	register(s, "commitments_add", "Record something the person commits to doing this week (or a given week) toward a goal. Weekly commitments should be few and small.", true, addCommitment)
	register(s, "commitments_list", "List the commitments for a week with how many are done.", false, listCommitments)
	register(s, "commitments_complete", "Mark a commitment done, or reopen it. Completing one that points at a step also completes the step.", true, completeCommitment)
	register(s, "commitments_delete", "Remove a commitment.", true, deleteCommitment)
	register(s, "plan_get", "Read a day's plan: items in order, any pending proposed revisions, and a summary. Defaults to today in the person's time zone.", false, getPlan)
	register(s, "plan_items_create", "Add something to a day's plan: a task, an event, preparation or a break. Mark at most a few items as priorities.", true, createPlanItem)
	register(s, "plan_items_update", "Replace a plan item's fields using the version you last read.", true, updatePlanItem)
	register(s, "plan_items_complete", "Mark a plan item done, or reopen it. Completing one linked to a step also completes the step.", true, completePlanItem)
	register(s, "plan_items_move", "Move a plan item to another day; its start time is cleared.", true, movePlanItem)
	register(s, "plan_items_delete", "Remove a plan item from the plan (it can be restored).", true, func(c context.Context, u *unit, in EditInput) (PlanItem, error) {
		return lifecyclePlanItem(c, u, in, false)
	})
	register(s, "plan_items_restore", "Restore a removed plan item.", true, func(c context.Context, u *unit, in EditInput) (PlanItem, error) {
		return lifecyclePlanItem(c, u, in, true)
	})
	register(s, "plan_replan_preview", "When the person's day changed: given the minutes they have left, show which open items still fit (priorities first) and which move to tomorrow. Deterministic and read-only; offer it with plan_propose.", false, previewReplan)
	register(s, "plan_propose", "Offer the person a revised plan for a day: add, move or drop items, with a reason in their terms. Nothing changes until they accept it in their app. Use this instead of silently rearranging their day.", true, createProposal)
	register(s, "plan_proposals_list", "List proposed plan revisions: pending by default.", false, listProposals)
	register(s, "plan_proposal_apply", "Accept a proposal, making all its changes at once. Fails if the plan changed since it was offered.", true, applyProposal)
	register(s, "plan_proposal_discard", "Decline a proposal.", true, discardProposal)
	register(s, "next_action", "The one thing to do with the minutes the person has: today's priorities first, then the next step of a goal, then anything else that fits. Returns null when nothing fits, which is a good moment to suggest a break.", false, nextAction)
	register(s, "routines_create", "Create a routine: something the person wants to DO repeatedly, such as drinking water 3 times a day, stretching each morning or running Monday, Wednesday and Friday. Use this, not reminders, for any repeating behaviour; if it serves a goal, link it with goals_link_routine; a reminder is only a one-off cue or an event. Give it a target_per_day (default 1), nudges (the times the person may be nudged, each an HH:MM and an optional wording hint; for example three for three times a day; a nudge belongs to its routine and is not a reminder), a short busy-day version and optional weekdays. It appears in their app with a tracker. Missed days are information, not failure.", true, createRoutine)
	register(s, "routines_get", "Read one routine.", false, func(c context.Context, u *unit, in GetInput) (Routine, error) { return u.getRoutine(c, in.ID, false) })
	register(s, "routines_list", "List the person's routines.", false, listRoutines)
	register(s, "routines_update", "Replace a routine's fields, including all of its nudges, using the version you last read. To change one nudge use nudges_set or nudges_remove instead.", true, updateRoutine)
	register(s, "nudges_set", "Add a nudge to a routine, or change the wording hint of the one at that time. A nudge is when the person may be prompted about the routine; it checks the day's count first and speaks only if the day is not done. It lives on the routine and never appears as a reminder. Uses the routine's version.", true, setNudge)
	register(s, "nudges_remove", "Remove the nudge at a time from a routine, using the routine's version.", true, removeNudge)
	register(s, "routines_delete", "Delete a routine (it can be restored).", true, func(c context.Context, u *unit, in EditInput) (Routine, error) {
		return lifecycleRoutine(c, u, in, false)
	})
	register(s, "routines_restore", "Restore a deleted routine.", true, func(c context.Context, u *unit, in EditInput) (Routine, error) {
		return lifecycleRoutine(c, u, in, true)
	})
	register(s, "routine_checkins_set", "Record that the person did a routine on a day, in its full or short version, or clear it with none. Idempotent per routine and day.", true, setCheckin)
	register(s, "routines_log", "Record that the person did a routine one more time today (or on a past day), or take one back with delta -1. A routine done several times a day (drink water 3 times) is done when the count reaches its target. Prefer this to routine_checkins_set for anything counted.", true, logRoutine)
	register(s, "routines_history", "A routine's recent days, how consistent the person has been over the last 7 and 30 days, and their best run, for a tracker. A missed day lowers the rate; it never resets the history to zero.", false, routineHistory)
	register(s, "routines_status", "How each routine is going on a day: done or not, the streak, days since the last check-in, whether there has been a gap of 3+ days, and a hint for an easy restart.", false, routinesStatus)
	register(s, "journal_create", "Save a journal entry in the person's words: what happened, how it went, what they learned. Connect it to goals when it relates to them, and add one adjustment for tomorrow if they chose one. Set source to agent and pass session_id when you write it for them.", true, createJournal)
	register(s, "journal_get", "Read one journal entry with its attachments.", false, func(c context.Context, u *unit, in GetInput) (JournalEntry, error) {
		return u.getJournal(c, in.ID, false)
	})
	register(s, "journal_list", "Browse or search the person's journal, newest first. Search finds words and phrases ('the Lisbon trip', 'felt anxious'); filter by date range or goal.", false, listJournal)
	register(s, "journal_update", "Replace a journal entry's fields using the version you last read.", true, updateJournal)
	register(s, "journal_delete", "Delete a journal entry (it can be restored).", true, func(c context.Context, u *unit, in EditInput) (JournalEntry, error) {
		return lifecycleJournal(c, u, in, false)
	})
	register(s, "journal_restore", "Restore a deleted journal entry.", true, func(c context.Context, u *unit, in EditInput) (JournalEntry, error) {
		return lifecycleJournal(c, u, in, true)
	})
	register(s, "notes_create", "Save a note, list or log the person wants to keep (markdown body, tags, optional goal). Use this for anything they want to look up later that is not a task, reminder or journal entry.", true, createNote)
	register(s, "notes_get", "Read one note with its attachments.", false, func(c context.Context, u *unit, in GetInput) (Note, error) { return u.getNote(c, in.ID, false) })
	register(s, "notes_list", "Browse or search the person's notes: pinned first, then most recently changed; filter by tag or goal.", false, listNotes)
	register(s, "notes_update", "Replace a note's fields using the version you last read.", true, updateNote)
	register(s, "notes_delete", "Delete a note (it can be restored).", true, func(c context.Context, u *unit, in EditInput) (Note, error) { return lifecycleNote(c, u, in, false) })
	register(s, "notes_restore", "Restore a deleted note.", true, func(c context.Context, u *unit, in EditInput) (Note, error) { return lifecycleNote(c, u, in, true) })
	register(s, "captures_create", "Save a raw one-line capture exactly as the person said it, to be sorted later. The app uses this offline; you can also use it when you cannot yet tell what something is.", true, createCapture)
	register(s, "captures_list", "List the person's captures: open ones (not yet sorted) by default, newest first.", false, listCaptures)
	register(s, "captures_resolve", "Mark a capture sorted after you created the right record from it (a reminder, plan item, journal entry, note or goal), naming what it became, or dismiss it.", true, resolveCapture)
	register(s, "attachments_upload_init", "Reserve an upload for a photo, voice memo, PDF or text file on a journal entry or note. Then PUT the exact bytes to upload_path with the matching Content-Type. Up to 25 MiB and 20 files per record.", true, s.initAttachment)
	register(s, "attachments_get", "Read an attachment's status and where to fetch its content.", false, func(c context.Context, u *unit, in GetInput) (Attachment, error) {
		return u.getAttachment(c, in.ID, false)
	})
	register(s, "attachments_delete", "Remove an attachment from its record (it can be restored).", true, func(c context.Context, u *unit, in EditInput) (Attachment, error) {
		return lifecycleAttachment(c, u, in, false)
	})
	register(s, "attachments_restore", "Restore a removed attachment.", true, func(c context.Context, u *unit, in EditInput) (Attachment, error) {
		return lifecycleAttachment(c, u, in, true)
	})
	register(s, "day_close", "Close the person's day: summarise it, move unfinished plan items to tomorrow, and save an optional one-or-two-line reflection to the journal with a suggested adjustment for tomorrow. Safe to repeat; nothing is lost.", true, dayClose)
	register(s, "week_stats", "What happened in a week: planned versus finished work, goal steps done, routine check-ins, journal entries, commitments, and one suggested change for next week.", false, weekStats)
	register(s, "life_context_get", "Everything you need to help the person with their day, week or a goal in one read: the plan, commitments, goals with next steps, reminders due, routines (with gaps), recent journal lines and weekly numbers, each with its version. Read this before suggesting, replanning or reflecting.", false, lifeContext)
	register(s, "history_list", "Read the audit trail of changes to a record, newest first.", false, history)
	register(s, "life_notify", "Tell the person something outside the conversation: it reaches this app as a notification (and its inbox), and no other app. Use it sparingly, for something they would want to know now or would miss; never for chatter, progress or things you can say in the reply. Link the record it is about so tapping opens it. Not for reminders (create a reminder) or timed work (arm a schedule).", true, notifyPerson)
	register(s, "events_pending", "Hand over the notices this engine has recorded and not yet delivered. Called by the hub's delivery loop, not by the agent.", false,
		func(c context.Context, u *unit, _ struct{}) (EventsResult, error) { return u.eventsPending(c) })
	registerKeyless(s, "events_ack", "Mark notices delivered so they are not handed over twice. Called by the hub's delivery loop, not by the agent.",
		func(c context.Context, u *unit, in AckEventsInput) (AckEventsResult, error) {
			return u.eventsAck(c, in)
		})
}
